<script>
(function(){
const form=document.getElementById('po-form'),lines=document.getElementById('po-lines');let next={{ max(array_map('intval',array_keys(old('items',[0=>[]]))))+1 }};
function recalc(){let sum=0;lines.querySelectorAll('tr').forEach(row=>{const q=Number(row.querySelector('[name$="[quantity]"]').value)||0,p=Number(row.querySelector('[name$="[unit_price]"]').value)||0,total=q*p;row.querySelector('.po-line-total').textContent=total.toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2});sum+=total});document.getElementById('po-subtotal').textContent=sum.toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2})}
lines.addEventListener('input',recalc);lines.addEventListener('click',e=>{if(e.target.closest('.po-remove')&&lines.querySelectorAll('tr').length>1){e.target.closest('tr').remove();recalc()}});recalc();
document.getElementById('po-add-line').addEventListener('click',()=>{if(lines.querySelectorAll('tr').length>=100)return;const i=next++,tr=document.createElement('tr');tr.className='po-line';tr.innerHTML='<td><input required maxlength="255" name="items['+i+'][description]" placeholder="Enter material or product"></td><td><input required type="number" step="0.0001" min="0.0001" name="items['+i+'][quantity]" value="1"></td><td><input required type="number" step="0.0001" min="0" name="items['+i+'][unit_price]" value="0"></td><td class="po-line-total">0.00</td><td><button type="button" class="po-button alt po-remove">Remove</button></td>';lines.appendChild(tr);recalc()});
document.querySelectorAll('[data-open-dialog]').forEach(btn=>btn.addEventListener('click',()=>{const dialog=document.getElementById(btn.dataset.openDialog);if(dialog.id==='po-supplier-dialog'&&!document.getElementById('po-currency').value){alert('Please select or create a currency first.');return}dialog.showModal()}));
document.querySelectorAll('[data-close]').forEach(btn=>btn.addEventListener('click',()=>btn.closest('dialog').close()));
document.querySelectorAll('form[data-quick]').forEach(quick=>quick.addEventListener('submit',async e=>{e.preventDefault();const submit=quick.querySelector('button[type="submit"],button:not([type])'),alertBox=quick.querySelector('.po-alert');submit.disabled=true;alertBox.hidden=true;const data=new FormData(quick);if(quick.dataset.quick==='supplier')data.append('currency_id',document.getElementById('po-currency').value);try{const response=await fetch(quick.action,{method:'POST',body:data,headers:{'Accept':'application/json','X-Requested-With':'XMLHttpRequest'}});const json=await response.json();if(!response.ok)throw new Error(json.message||(json.errors?Object.values(json.errors).flat().join(' '):'Unable to save'));const select=document.getElementById(quick.dataset.quick==='supplier'?'po-supplier':'po-currency');select.add(new Option(json.text,json.id,true,true));if(window.jQuery)jQuery(select).trigger('change');quick.closest('dialog').close();quick.reset()}catch(error){alertBox.textContent=error.message;alertBox.hidden=false}finally{submit.disabled=false}}));
})();
</script>
